{
  "apiVersion": 1,
  "type": "component.detail.props",
  "package": "@astryxdesign/lab",
  "data": [
    {
      "name": "label",
      "type": "string",
      "description": "Required accessible action name and hover/focus tooltip. Include grouped, unread, or resolved context when it changes the action meaning, for example “Open 4 grouped annotations from Ada and Lin, 2 unread”.",
      "required": true
    },
    {
      "name": "participants",
      "type": "readonly [CommentPinParticipant, ...CommentPinParticipant[]]",
      "description": "Non-empty ordered participants, lead first. A single pin renders the first. A grouped pin renders distinct IDs as an AvatarGroup of at most three circles: every participant when three or fewer are distinct, otherwise the first two plus an ellipsis overflow circle. Pass every distinct participant so the overflow appears exactly when more than three people participate. Each record has id, name, and optional avatarSrc.",
      "required": true
    },
    {
      "name": "size",
      "type": "'sm' | 'md' | 'lg'",
      "description": "Pin height on the element-size scale: sm 28px, md 32px, lg 36px, with 22px, 24px, and 28px participant circles. Padding is equal on every side, so the avatars and overflow sit the same distance from each edge; the trailing count or unread dot adds a little end padding so it never crowds the edge.",
      "default": "'sm'"
    },
    {
      "name": "threadCount",
      "type": "number",
      "description": "Total represented threads. A finite positive integer above one switches to grouped presentation and displays the exact count. The host still owns the clustering policy.",
      "default": "1"
    },
    {
      "name": "unreadCount",
      "type": "number",
      "description": "Represented threads with unread activity. When above zero, an accent status dot appears at the end of the pin, after the thread total or the single participant; the number itself is not shown. Invalid values are ignored and values above threadCount are capped. Repeat the unread context in label.",
      "default": "0"
    },
    {
      "name": "isSelected",
      "type": "boolean",
      "description": "Whether the pin is the active annotation target. Draws a solid 2px accent outline outside the pin, keeping its elevation, plus aria-pressed; the shared offset focus outline remains farther outside for keyboard focus. Follow aria-pressed toggle semantics: activating the selected pin again should clear the host selection.",
      "default": "false"
    },
    {
      "name": "isDimmed",
      "type": "boolean",
      "description": "Whether another pin is selected. Lowers this pin’s opacity without disabling it, so it remains available to switch selection. Leave it false on every pin when nothing is selected. Selected presentation wins if both are true.",
      "default": "false"
    },
    {
      "name": "isResolved",
      "type": "boolean",
      "description": "Whether every represented thread is resolved. A resolved pin renders nothing unless it is selected: resolved discussion leaves the content, while a thread the reader opened (or resolved from its popover) keeps its anchor, with the selected treatment, until the host clears the selection.",
      "default": "false"
    },
    {
      "name": "isDisabled",
      "type": "boolean",
      "description": "Disables activation: the pin exposes aria-disabled, keeps its tab stop, and blocks every activation path. Useful for a pending anchor before its thread exists.",
      "default": "false"
    },
    {
      "name": "onClick",
      "type": "MouseEventHandler<HTMLButtonElement>",
      "description": "Product-owned activation handler. Open or select the represented thread/group here; CommentPin owns no comments or popover state."
    },
    {
      "name": "xstyle",
      "type": "StyleXStyles",
      "description": "StyleX layout customization for the button root. Hosts may position it over content or in a margin; absolute anchors map to the logical bottom-start corner by placing the inline-start edge at the anchor and translating the pin upward by its full height."
    }
  ],
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
